import re
import subprocess
import zipfile
from itertools import cycle, islice

from pprint import pformat
from typing import List, Optional
from xml.etree import ElementTree as Et

from taf.rfrl.csv4all.resources.notifications.email_format import EmailFormat
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.test_cases import UpgradeRollbackTest, UpgradeTest
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import ImportSwToNetactError, CopySwToNetactError
from taf.rfrl.csv4all.resources.node.feature.netact.netact import Netact
from taf.rfrl.csv4all.resources.node.feature.utilities.nescrotta.nescrotta import Nescrotta
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, function_wrapper, wrapper_decorator
from taf.rfrl.csv4all.resources.node.feature.netact.netact_node_factory import NetactNodeFactory
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success


class NetactFeatureTest(UpgradeRollbackTest):

    def __init__(self, nodes_details, test_nodes_details: List[dict], iterations_per_node: int,
                 netact_dict: dict, report: bool, calculate_kpi: Optional[bool] = True,
                 kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = False,
                 feature: Optional[str] = None, rollback: Optional[bool] = True, fallback: Optional[bool] = False,
                 stop_test_after_fail: bool = False, deintegrate_after_test: bool = True,
                 integrate_before_test: bool = True, config_type: str = None,
                 artifactory_location: str = "espoo2", package_suffix: str = "A54",
                 l3_call_method: Optional[callable] = None, synchronize_software_on_passive: bool = False,
                 yaft_path: str = "/home/ute", virtualenv_dir: str = None, rollback_reverse_order: bool = False,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0, cm_provision: bool = True,
                 diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, use_external_storage, download_path,
                         use_testpackage, restore_to_target_sw, l3_call_method, stop_test_after_fail,
                         artifactory_location, package_suffix, synchronize_software_on_passive, yaft_path,
                         virtualenv_dir, rollback_reverse_order, detailed_console_log,
                         collect_passed_logs=collect_passed_logs, diagnostic_check=diagnostic_check)
        self.feature = feature
        self.netact_dict = netact_dict
        self.config_type = config_type
        self.node_factory = NetactNodeFactory()
        self.netact = Netact(**self.netact_dict)
        self.nescrotta = None
        self.perform_rollback = rollback
        self.perform_fallback = fallback
        self.restore_to_target_sw = restore_to_target_sw
        self.node_master = None
        self.deintegrate_after_test = deintegrate_after_test
        self.integrate_before_test = integrate_before_test
        if self.report_to_rp:
            self.test_reporter.tool = "MantaRay"
        self.check_cm_provision = cm_provision

    def test_setup(self):
        self.setup_for_netact_test()
        self.setup_nescrotta()
        self.prepare_uboot_scripts()
        self.setup_netact_and_integrate_nodes()
        self.prepare_sw_packages()
        self.set_netact_target_list()

    def setup_for_netact_test(self):
        super(UpgradeTest, self).test_setup()
        self._log_if_reports_to_uuf_wont_be_sent()
        self.check_source_and_target_sw()
        self.prepare_uboot_scripts()
        self.yaft_checkout()
        self.check_validation_scf_before_test()
        self.hwf_migration_precheck()
        self.check_oran_files_exists()

    def test(self):
        self.run_iteration_precondition()
        self.failed_nodes = self.test_operation(None)
        self.report_results_to_uuf_dashboard()
        self.run_iteration_postcondition(None)
        if self.perform_fallback:
            if self.perform_rollback:
                self.preparation_before_fallback()
                operation_name = "update_before_fallback"
                self.software_update_test(operation_name)
                if not self.passed_logs_gathered:
                    self.gather_mumin_logs_and_snapshot(operation_name)
            self.software_fallback_test()
        self.verify_failed_nodes_after_iteration()

    def test_operation(self, node):
        self.set_timestamp_reporting_and_kpi()
        if not self.perform_rollback and self.perform_fallback:
            self.preparation_before_fallback()
        self.software_update_test()
        if self.perform_rollback:
            self.software_rollback_test()
        return self.failed_nodes

    @wrapper_decorator
    def update_sw(self, node, operation: str = "update"):
        super()._update_sw(node, operation)
        self._netact_check_after_operation(node, "update", self.failed_nodes_during_update, self.check_cm_provision)

    def software_update_test(self, operation: str = "update"):
        with RobotWrapper("Software Update Test", "kw"):
            for node in self.test_nodes:
                if self.use_testpackage:
                    node.netact_target_sw = next(node.iter_target_sw_list)
                else:
                    node.netact_target_sw = self.get_target_sw(node.target_sw)
                self.update_sw(node, operation)

    @wrapper_decorator
    def rollback_sw(self, node):
        super()._rollback_sw(node)
        self._netact_check_after_operation(node, "rollback", self.failed_nodes_during_rollback)

    def software_rollback_test(self):
        with RobotWrapper("Software Rollback Test", "kw"):
            test_nodes = self.test_nodes[::-1] if self.rollback_reverse_order else self.test_nodes
            for node in test_nodes:
                self.rollback_sw(node)

    def software_fallback_test(self):
        with RobotWrapper("Software Fallback Test", "kw"):
            for node in self.test_nodes:
                self._fallback_sw(node)

    @wrapper_decorator
    def _fallback_sw(self, node):
        if self.check_nodes_state_before_fallback(node):
            self.failed_nodes[node.node_alias].update(self.sw_fallback_operation(node))

    @method_decorator()
    def sw_fallback_operation(self, node):
        test_logger("Fallback Test started")
        operation = "fallback"
        node.logsverify.reset_check = False
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            node.execute_reset_loop()
            node.reset_admin()
            self.verify_active_sw_after_fallback(node)
            node.verify_node_after_fallback()
            self.check_connection_after_fallback_and_collect_snapshot(node)
            test_logger(f"[{node.node_alias}] {operation.upper()} PASSED", hyperlink=True)
            return set()
        except Exception as e:
            test_logger(f"[{node.node_alias}] {operation.upper()} FAILED", "error")
            try:
                self.gather_mumin_logs_and_snapshot(operation)
            except Exception as e:
                test_logger(e, console=False)
            return {node.mrbts_id}
        finally:
            node.logsverify.reset_check = True
            node.cleanup_after_fallback()
            if node.netboot_changed:
                node.change_netboot_state("on")

    @method_decorator()
    def check_connection_with_netact(self, node, cm_provision=False):
        try:
            node.check_connection_to_netact()
            if cm_provision:
                node.cm_provision()
                node.verify_node_bts_state()
            self.check_cm_provision = False
            return set()
        except Exception as e:
            test_logger(e, "DEBUG")
            return {node.node_alias}

    @method_decorator()
    def check_connection_after_fallback_and_collect_snapshot(self, node):
        operation = "fallback"
        if self.check_connection_with_netact(node):
            raise
        if not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot(operation)
            self.send_snapshot_to_nescrotta(node, operation)

    @method_decorator()
    def check_nodes_state_before_rollback(self, node):
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.gather_mumin_logs_and_snapshot("before_rollback")
            try:
                self.run_recovery_method(failed_nodes)
            except Exception as e:
                self.failed_nodes[node.node_alias].update(failed_nodes)
                test_logger(e, "error")
            return False
        try:
            node.verify_active_sw_version(node.target_sw)
            return True
        except WrongSwVersion:
            return False

    @method_decorator()
    def check_nodes_state_before_fallback(self, node):
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.gather_mumin_logs_and_snapshot("before_fallback")
            try:
                self.run_recovery_method(failed_nodes)
            except Exception as e:
                self.failed_nodes[node.node_alias].update(failed_nodes)
                test_logger(e, "error")
                return False
        return True

    @wrapper_decorator
    def _postcondition(self, node):
        try:
            node.verify_active_sw_version(node.source_sw if self.perform_rollback else node.target_sw)
        except WrongSwVersion:
            if self.perform_rollback:
                node.perform_rollback_and_wait_for_reload()
                node.verify_node_state(1200, 30)
            else:
                raise WrongSwVersion()

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            super().test_teardown()
        finally:
            if self.deintegrate_after_test:
                for node in self.test_nodes:
                    try:
                        node.deintegrate_mrbts()
                    except Exception:
                        test_logger("Deintegration failed", "error")
            self.teardown_netact()
            self.umount_nescrotta()

    @method_decorator()
    def import_sw_to_netact(self, sw_lists_to_import):
        test_logger("Import SW to Netact")
        for sw_build in sw_lists_to_import:
            netact_target_build = self.get_target_sw(sw_build)
            is_imported = False
            if netact_target_build.split("_")[0] != "SBTS00":
                is_imported = self.node_master.netact.is_imported_sw(netact_target_build)
            if not is_imported:
                self.download_builds_from_wft(sw_build)
                if self.use_testpackage:
                    sw_build_path_list = {sw_path for sw_build, sw_path in self.wft.target_sw_dict.items()
                                          if sw_build.startswith(self.node_master.target_sw)}
                else:
                    sw_build_path_list = [self.wft.target_sw_dict.get(f"{sw_build}_release_BTSSM_downloadable_"
                                                                      f"{self.package_suffix}")]
                for sw_build_path in sw_build_path_list:
                    self.copy_sw_to_netact(sw_build_path)
                    try:
                        netact_target_build = self.get_target_sw(sw_build)
                        is_imported = self.node_master.netact.is_imported_sw(netact_target_build)
                        if not is_imported:
                            test_logger("Importing SW")
                            self.node_master.netact.import_sw(self.get_target_sw(sw_build),
                                                              self.get_compatibility_releases_from_package(
                                                                  sw_build_path))
                    except Exception as e:
                        test_logger(e, console=False)
                        raise ImportSwToNetactError("Importing SW to Netact failed")
            else:
                test_logger(f"{sw_build} is already imported")

    @staticmethod
    def get_compatibility_releases_from_package(sw_build_path: str) -> list:
        try:
            with zipfile.ZipFile(sw_build_path, "r") as package:
                tree = Et.parse(package.open('sw_compatibility.xml'))
                return [elem.text for elem in tree.iter() if 'release-name' in elem.tag]
        except zipfile.BadZipfile as e:
            test_logger("Provided package is wrong, couldn't get compatibility releases")
            test_logger(e, console=False)
            return []

    @method_decorator()
    def check_provision_from_target_sw(self, node):
        try:
            test_logger(f"Checking provision to {node.netact_target_sw} from same software")
            node.netact.provision_sw(node.netact_target_sw, node.mo_dist_name)
            test_logger(f"PROVISION CHECK FROM SAME SOFTWARE PASSED", hyperlink=True)
            return set()
        except Exception as e:
            test_logger(f"PROVISION CHECK FROM SAME SOFTWARE FAILED", log_level="ERROR")
            test_logger(e, "error")
            return {node.node_alias}

    @function_wrapper
    def send_snapshot_to_nescrotta(self, node, operation: str):
        if self.nescrotta:
            test_logger("Checking if sending snapshot to Nescrotta is possible")
            self.nescrotta.send_snapshot_to_nescrotta(f"{self.current_logs_dir}/{operation}/{node.node_alias}",
                                                      operation.capitalize())

    @function_wrapper
    def copy_sw_to_netact(self, sw_path: str):
        test_logger("Copying SW to Netact")
        sw_package_name = re.sub("_release.*", "", sw_path.split("/")[-1], count=0, flags=0)
        if any(sw_package_name.endswith(tp) for tp in ["T1", "T2"]):
            testpackage = sw_package_name.replace(sw_package_name, "")
            sw_package_name = sw_package_name.replace(testpackage, "")
        else:
            testpackage = ""
        target_sw = self.get_target_sw(sw_package_name)
        command = f"sshpass -p '{self.node_master.netact.ssh_password}' scp -v -o UserKnownHostsFile=/dev/null -o " \
                  f"StrictHostKeyChecking=no {sw_path} " \
                  f"{self.node_master.netact.ssh_username}@{self.node_master.netact.netact_was_node_ip}:" \
                  f"{self.node_master.netact.swm_temp_dir}/{target_sw}{testpackage}.zip"
        process = subprocess.Popen(command, shell=True, universal_newlines=True,
                                   stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        output, error = process.communicate()
        if process.returncode != 0:
            raise CopySwToNetactError(output, error)

    def prepare_sw_packages(self):
        self.node_master = self.test_nodes[0]
        sw_lists_to_import = {self.node_master.target_sw}
        for node in self.test_nodes:
            if self._check_if_sw_are_similar(node):
                self.download_builds_from_wft(node.target_sw)
                break
            if self.use_testpackage:
                target_sw_names = [node.target_sw, f"{node.target_sw}T1", f"{node.target_sw}T2"]
                target_sw_list = list(islice(cycle(target_sw_names), self.iterations_per_node + 1))
                node.iter_target_sw_list = iter(target_sw_list)
        if self.perform_fallback:
            for node in self.test_nodes:
                sw_lists_to_import.add(node.source_sw)
        self.import_sw_to_netact(sw_lists_to_import)

    @method_decorator()
    def setup_nescrotta(self):
        if self.feature and self.config_type:
            target_release = self.wft.get_sw_release(self.test_nodes[0].target_sw).replace('SBTS', '')
            source_release = target_release if "SBTS00" in self.test_nodes[0].source_sw else \
                self.wft.get_sw_release(self.test_nodes[0].source_sw).replace('SBTS', '')
            self.nescrotta = Nescrotta(target_release, source_release, self.feature, self.config_type, tool="MantaRay")
            self.mount_nescrotta()

    def umount_nescrotta(self):
        if self.nescrotta:
            self.nescrotta.umount_nescrotta()

    def mount_nescrotta(self):
        if self.nescrotta:
            self.nescrotta.mount_nescrotta()

    def get_target_sw(self, sw_build: str) -> str:
        if "SBTS00" in sw_build:
            return sw_build.replace("SBTS00", self.wft.get_sw_release(sw_build))
        return sw_build

    def setup_netact_and_integrate_nodes(self):
        self.setup_netact()
        for node in self.test_nodes:
            node.netact = self.netact
            node.mplane = node.set_node_mplane()
            if self.integrate_before_test:
                node.integrate_mrbts()

    @function_wrapper
    def setup_netact(self):
        self.netact.setup_netact()
        self.log_netact_information()

    @function_wrapper
    def log_netact_information(self):
        netact_vars = vars(self.netact).copy()
        netact_vars["ssh_password"] = ""
        test_logger(pformat(netact_vars), console=False)

    @function_wrapper
    def teardown_netact(self):
        self.netact.teardown_netact()

    @method_decorator()
    def send_email(self, state: str, msg: str = ""):
        try:
            iteration_number = self.current_iteration.split("_")[1] if self.current_iteration else "1"
            email_body = EmailFormat(self.nodes, self.test_nodes, self.report_to_rp, self.test_reporter,
                                     self.iterations_per_node, state, msg, self.topology,
                                     self.get_execution_log_link(), self.test_results,
                                     iteration_number, self.netact_dict["name"])
            self.notifications.send_email(body=str(email_body),
                                          subject=f"CSV4ALL {self.test_name_titlecase} {state.upper()} on "
                                                  f"{', '.join([node.hostname for node in self.test_nodes])}")
        except Exception as e:
            test_logger(e, "warn")

    def _netact_check_after_operation(self, node, operation: str, failed_nodes, cm_provision: bool = False):
        if operation == "update":
            failed_nodes.update(self.check_provision_from_target_sw(node))
        failed_nodes.update(self.check_connection_with_netact(node, cm_provision))
        failed_nodes.update(self.verify_cells_via_netact(node))
        self.summary_operation(node, operation, failed_nodes)
        if not failed_nodes and not self.passed_logs_gathered:
            self.send_snapshot_to_nescrotta(node, operation)
        self.failed_nodes[node.node_alias].update(failed_nodes)

    def _precondition(self, node):
        super()._precondition(node)
        if not self.perform_rollback and self.perform_fallback:
            node.prepare_node_before_fallback()

    def set_netact_target_list(self):
        if self.use_testpackage:
            for node in self.test_nodes:
                target_sw_list = {node.target_sw}
                target_sw_list.update({node.target_sw+tp for tp in ["T1", "T2"]})
                target_sw_paths_list = list(islice(cycle(target_sw_list), self.iterations_per_node + 1))
                node.iter_target_sw_list = iter(target_sw_paths_list)

    @method_decorator()
    def verify_cells_via_netact(self, node):
        try:
            wait_until_success(120, 20, node.verify_cells_via_netact)
            return set()
        except Exception as e:
            test_logger(e, "ERROR")
            return {node.node_alias}

    @method_decorator()
    def verify_active_sw_after_fallback(self, node):
        node.verify_active_sw_version(node.source_sw)

    @method_decorator()
    def preparation_before_fallback(self):
        for node in self.test_nodes:
            node.precondition_before_fallback()
